def build(lang):
    pack = lambda rows: [{'intro': i, 'points': p} for i, p in rows]
    return {'ui': UI[lang], 'services': pack(SERVICES[lang]), 'roles': pack(ROLES[lang]), 'sectors': pack(SECTORS[lang])}


